# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊 kanna → 拉丁 canna','芦苇；细长的茎或管']]
K=[['希腊 kanon','直杆、量尺 → 标准'],['拉丁 canon','规则；权威认可的规范']]
W=[
E('cane','/keɪn/','藤条或类似的细长茎；手杖；用杖责打','先想一根细长的植物茎：可以拿来支撑身体，也可以编东西。','古法语 cane → 英语 cane，上接拉丁 canna 和希腊 kanna。更早可能与闪米特语言中表示芦苇的词有关。',B+[['古法语 cane → 英语 cane','植物茎 → 手杖、藤条']],'walk with a cane 是拄杖走路，手杖今天不必真用植物茎做。cane furniture 常指藤编家具，sugar cane 指甘蔗；动词 cane 是用藤条或杖打人，常见于历史叙述。','a walking cane；cane furniture；sugar cane；cane somebody。','cane 不是 can 的变形；can 表示能或罐子的两条词源，都不能直接接到这根芦苇上。',('He walked slowly with a cane in his right hand.','他右手拄着手杖，慢慢地走。'),('The old cane chair had a woven seat.','那把旧藤椅有一张编织的椅面。'),sources=['https://www.etymonline.com/word/cane','https://en.wiktionary.org/wiki/cane']),
E('sugarcane','英 /ˈʃʊɡəkeɪn/；美 /ˈʃʊɡərkeɪn/','甘蔗','把 sugar 糖和 cane 细长的植物茎放一起：茎里有甜汁、能用来制糖的植物。','英语 sugar + cane 的复合词；也常分写 sugar cane。cane 的历史接拉丁 canna。',B+[['英语 cane + sugar → sugarcane','能提供糖的植物茎 → 甘蔗']],'sugarcane 常当作作物名称，不可数；说一根时可以用 a stalk of sugarcane。sugarcane juice 是甘蔗汁，cane sugar 是以甘蔗为来源的糖。','grow sugarcane；harvest sugarcane；sugarcane juice；a sugarcane field。','sugarcane 是植物，cane sugar 是糖。词序改变，中心物也变了：前者是 cane，后者是 sugar。',('The farmers harvested sugarcane before the rains began.','农民在雨季开始前收割了甘蔗。'),('The stall sells fresh sugarcane juice.','那个摊位出售现榨甘蔗汁。'),sources=['https://en.wiktionary.org/wiki/sugarcane','https://www.oxfordlearnersdictionaries.com/definition/english/sugar-cane']),
E('canister','英 /ˈkænɪstə/；美 /ˈkænɪstər/','罐；筒状容器','最早是把芦苇编成的篮子；后来名称换到了装东西的罐和筒上。','希腊 kanystron 芦苇篮 → 拉丁 canistrum → 英语 canister；不是英语 can 加一个 -ister 后缀。',B[:1]+[['希腊 kanystron → 拉丁 canistrum','用芦苇编的篮子'],['英语 canister','篮子 → 小型金属容器、罐筒']],'a tea canister 是茶叶罐，a gas canister 是气体罐。容器通常较结实，常有盖或密封结构。词义转向金属罐时受了不同来源的 can 影响，这是词之间互相影响，不是本来就由 can 派生。','a tea canister；a gas canister；a film canister。','canister 常让人想到较结实的储存罐或压力罐，container 是更宽泛的容器；它们不能在所有场合直接互换。',('She keeps loose tea in a metal canister.','她把散茶放在一个金属茶叶罐里。'),('The museum displayed old film canisters beside the projector.','博物馆在放映机旁展出了旧胶片筒。'),sources=['https://www.etymonline.com/word/canister','https://en.wiktionary.org/wiki/canister']),
E('canon','/ˈkænən/','公认的经典作品集合；正式设定；规范；卡农','先想一把量尺：用它判断什么算符合标准，再引申成被正式认可的规则或作品。','英语经拉丁语及法语路线接希腊 kanon 量尺、标准。kanon 与 kanna 芦苇的远源联系有争议，不能断言两者一定同源。',K+[['古英语 canon／古法语 canon → 英语 canon','宗教规则、正典 → 认可的经典或设定']],'the literary canon 是被视为经典的一批作品；粉丝说某剧情 is canon，是说它属于作品正式承认的设定。音乐中的 canon 指按规则让声部先后模仿同一旋律的卡农。另有教士义，经 canonicus 这条名词化路线而来。','the literary canon；the biblical canon；part of the canon；This is canon。','canon 不是“凡是很受欢迎的作品”；关键是被某个传统或作品体系认可。cannon 多一个 n，指大炮，读音相同。',('The course examines how books enter the literary canon.','这门课探讨书籍如何进入公认的文学经典之列。'),('Fans debate whether the alternate ending is part of the canon.','粉丝们争论另一个结局是否属于正式剧情。'),sources=['https://www.etymonline.com/word/canon','https://en.wiktionary.org/wiki/canon']),
E('canonical','英 /kəˈnɒnɪkəl/；美 /kəˈnɑnɪkəl/','被认可为标准的；属于正典的；规范的','一个对象有好几种写法或版本，选出那种被当作标准、正式认可的。','历史借自中世纪拉丁 canonicalis，上接 canonicus；现代可按 canon + -ical 理解关系。',K+[['拉丁 canonicus → 中世纪拉丁 canonicalis','按规则的；属于正典的'],['英语 canonical','规范的、权威认可的']],'a canonical text 是被承认为正典或经典的文本；a canonical form 是约定采用的规范形式；故事的 canonical ending 是正式认可的结局。这个词不保证客观上最好，只说明它在相应体系中有标准地位。','a canonical text；the canonical version；canonical form；a canonical example。','canonical 强调标准地位，typical 强调有代表性。一个例子很典型，不一定是公认的标准示例。',('The software converts each address to a canonical form.','软件会把每个地址转换成统一的规范形式。'),('The new edition preserves the canonical ending of the story.','新版保留了故事正式认可的结局。'),sources=['https://www.etymonline.com/word/canonical','https://en.wiktionary.org/wiki/canonical']),
E('canonically','英 /kəˈnɒnɪkli/；美 /kəˈnɑnɪkli/','按正典设定；按规范形式；依教会法规','给一句判断加一个范围：我是按正式设定或既定规范来说的。','canonical + -ly；词尾 -al 接 -ly 后常读成较紧凑的 /kli/。',K+[['canonical → canonically','规范的 → 按规范、按正式设定']],'Canonically, they are siblings 是说按官方剧情他们是兄弟姐妹；数学或计算中的 canonically represented 说按某个规范表示。这个副词的重点是依据哪套标准，而不是作者在表达“很经典”。','canonically represented；canonically equivalent；Canonically, ...。','canonically true 是在相应正典设定中为真，不等于现实生活中为真。不要把虚构作品的规则和现实事实混在一起。',('Canonically, the two characters have never met.','按正式剧情设定，这两个角色从未见过面。'),('The system stores equivalent expressions canonically.','系统用规范形式存储等价的表达式。'),sources=['https://en.wiktionary.org/wiki/canonically','https://www.oxfordlearnersdictionaries.com/definition/english/canonically']),
E('canonize','/ˈkænənaɪz/','正式封为圣人；把某人或作品奉为经典','不是单纯说“我喜欢他”，而是把他放进被正式认可、享有特殊地位的名单。','古法语 canonisier／中世纪拉丁 canonizare → 英语；现代可看出 canon + -ize。',K+[['中世纪拉丁 canonizare／古法语 canonisier','纳入认可的名单；封圣'],['英语 canonize','封圣；比喻奉为经典']],'宗教语境里，canonize somebody 是正式封圣。文学评论也会说 critics canonized the poet，意思是评论界把这位诗人推上经典地位，未必带宗教含义。','canonize somebody；be canonized；canonize an author；英国英语也写 canonise。','praise 是赞扬，canonize 的比喻义更强：把对象捧到具有权威或近乎不可质疑的地位。',('The ceremony marked the decision to canonize the priest.','这场仪式标志着正式封那位神父为圣人的决定。'),('The essay questions how critics canonize some writers and overlook others.','这篇文章追问评论家为何把一些作家奉为经典，却忽视另一些人。'),sources=['https://www.etymonline.com/word/canonize','https://www.oxfordlearnersdictionaries.com/definition/english/canonize']),
E('canonise','/ˈkænənaɪz/','封圣；奉为经典〔英国英语常见拼写〕','和 canonize 是同一个动作：把对象纳入正式认可的名单或经典行列。','对应 canonize 的 -ise 拼写；接法语及拉丁 canonizare 词族。',K+[['canonizare → canonize／canonise','封圣；正式奉为权威']],'canonise 常见于采用 -ise 的英国英语文本。s 仍读 /z/，与 canonize 没有词义差异；英国英语也能用 -ize，不宜把它划成绝对的国别界线。','canonise a saint；canonise a writer；be canonised。','canonise 说正式认可或奉为经典，canonical 说已经属于相应规范或正典；一个是动作，一个是性质。',('The article explains why the church chose to canonise her.','这篇文章解释了教会为何决定将她封为圣人。'),('We should not canonise a writer so completely that criticism becomes impossible.','我们不应把一位作家奉到完全不容批评的地位。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/canonize','https://en.wiktionary.org/wiki/canonise']),
E('canonization','英 /ˌkænənaɪˈzeɪʃən/；美 /ˌkænənəˈzeɪʃən/','封圣；经典地位的确立','把“封为圣人、奉为经典”这件事作为一个过程来谈。','历史接中世纪拉丁 canonizatio；现代可关联 canonize + -ation，但不必把名词说成必然由现代英语动词新造。',K+[['中世纪拉丁 canonizare → canonizatio','纳入认可名单 → 这一行为'],['英语 canonization','封圣；经典化过程']],'the canonization of an author 在文学史里可以讨论：谁选进教材、谁得到反复研究、谁最终被认作必读经典。宗教语境里则回到正式封圣的过程或仪式。','the canonization of somebody；a canonization ceremony；literary canonization。','canonization 不是一般的 popularity 流行。它说地位被正式或持续确立，而不仅是眼下很多人喜欢。',('Thousands attended the canonization ceremony.','数千人参加了封圣仪式。'),('The chapter examines the poet’s gradual canonization.','这一章考察了这位诗人如何逐渐取得经典地位。'),sources=['https://www.etymonline.com/word/canonization','https://www.oxfordlearnersdictionaries.com/definition/english/canonization'])
]
